// Pull the model's JSON out of its reply. Anything unparseable is held
// for a human rather than guessed at.
const row = $('Get new requests').item.json;
const text = ($json.content ?? []).filter(c => c.type === 'text').map(c => c.text).join('') || $json.text || '';
let out;
try {
  out = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (e) {
  out = { verdict: 'needs_review', summary: 'Model reply could not be parsed', reply_draft: '' };
}
const verdicts = ['spam', 'not_fit', 'lead'];
const verdict = verdicts.includes(out.verdict) ? out.verdict : 'needs_review';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    id: row.id,
    email: row.email,
    name: row.name,
    idea: row.idea,
    status: verdict,
    summary: String(out.summary ?? '').slice(0, 300),
    reply_draft: verdict === 'lead' ? String(out.reply_draft ?? '').slice(0, 3000) : '',
    reviewed_at: new Date().toISOString(),
    telegram:
      `<b>New lead from gthanasis.com</b>\n` +
      `${esc(row.name || '(no name)')} &lt;${esc(row.email)}&gt;\n\n` +
      `${esc(out.summary)}\n\n` +
      `<i>They wrote:</i>\n${esc(String(row.idea).slice(0, 1200))}\n\n` +
      `<i>Draft reply:</i>\n${esc(String(out.reply_draft ?? '').slice(0, 1500))}`,
  },
};
